files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-block-size: 100dvb;
  margin: 0;
  padding: 40px;
  font-family: var(--main-font-family), sans-serif;
  font-size: var(--main-text-size, 18px);
  background-color: var(--white, #fff);
  background-image: var(--bg-pattern);
}

h2,
h3,
p,
ul {
  margin: 0;
  padding: 0;
}

ul {
  list-style: none;
}

h2 {
  font-weight: 800;
  font-size: var(--h2-font-size, 38px);
  text-transform: uppercase;
}

h3 {
  font-weight: 800;
  font-size: var(--h3-font-size, 31px);
  text-transform: uppercase;
}

.books {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px 10px;
}

.books__title {
  grid-column: 1 / 4;
}

.more-link {
  display: flex;
  justify-content: center;
  align-items: center;
  align-self: center;
  border: 1px solid var(--black, #000);
  padding: 10px 30px;
  color: var(--black, #000);
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-align: center;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #ffc802;
}

.more-link:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.more-link:focus {
  outline: 2px solid var(--black, #000);
  outline-offset: 0;
}

.books__list {
  grid-column: 1 / -1;
}

.books__list-item:not(:last-of-type) {
  margin-block-end: 20px;
}

.book-card {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  border: 1px solid var(--black, #000);
  background-color: #fff;
}

.book-card__cover {
  inline-size: 200px;
}

.book-card__description {
  flex-grow: 1;
  flex-basis: 400px;
  padding: 1em;
}

.book-card__title {
  margin-block-end: 0.5em;
}
@media (max-width: 600px) {
  body {
    padding: 10px;
  }

  .books {
    grid-template-columns: 1fr;
  }

  .books__title {
    grid-column: 1;
  }

  .more-link {
    grid-row: 3;
  }
}
